"""Text templates embedded from the full Tobias Holzmann case."""

FILES = {
    '.color': "#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Februar 2025                 #\n#----------------------------------------------#\n# Location:    www.Holzmann-cfd.de             #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n# Color definition for some bash highlight manipulation\n#------------------------------------------------------------------------------\nRED='\\e[0;31m'\nGREEN='\\e[0;32m'\nNC='\\e[0m'\nORANGE='\\033[0;33m'\nGRAY='\\e[0;37m'\nFL='\\033[0;36m'\n\n\n#------------------------------------------------------------------------------\n",
    '.preamble': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Februar 2025                 #\n#----------------------------------------------#\n# Location:    https://Holzmann-cfd.com        #\n# Email:       community@Holzmann-cfd.com      #\n#----------------------------------------------#\n\n\n#------------------------------------------------------------------------------\n# Preamble with the information about the tutorial\necho -en "\n-------------------------------------------------------------------------------\n${GRAY}Tutorial by Tobias Holzmann${NC} :: Generated during April 2016\n${GRAY}Build for OpenFOAM version${NC}  :: OpenFOAM-12\n${GRAY}Tested on system${NC}            :: Ubuntu 24.04.1\n${GRAY}The case was updated on${NC}     :: 10 Februar 2025\n-------------------------------------------------------------------------------\n\n\n${GREEN}Topic: Bifluidic Oscillator (Special tutorial for followers)${NC}\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\n# Check the OpenFOAM version\necho -e "   - Check OpenFOAM version. We need $foamVersion"\nuserFoamVersion=`echo "$WM_PROJECT-$WM_PROJECT_VERSION"`\n\nif [ "$userFoamVersion" == "$foamVersion" ]\nthen\n    echo -e  "   - ${GREEN}$foamVersion found...${NC}"\n\nelse\n    echo -e  "   - ${ORANGE}You are not using the correct OpenFOAM version"\n    echo -en "    Your version is $userFoamVersion and we need ${GREEN}"\n    echo -e  "$foamVersion${NC}\\n"\n\n    while true\n    do\n        echo -en  "   - Proceed with your OpenFOAM version (y/n): "\n        read proceed\n\n        if [ "$proceed" == "y" ]\n        then\n            break\n\n        elif [ "$proceed" == "n" ]\n        then\n            echo -e "\\n\\n"\n            exit\n\n        fi\n    done\nfi\n\n\n#------------------------------------------------------------------------------\n',
    '0.orig/S': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      S;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 0 0 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    back\n    {\n        type            empty;\n    }\n    freeWalls\n    {\n        type            zeroGradient;\n    }\n    front\n    {\n        type            empty;\n    }\n    inlet\n    {\n        type            fixedValue;\n        value           uniform 0;\n    }\n    top \n    {\n        type            inletOutlet;\n        inletValue      uniform 0;\n        value           uniform 0;\n    }\n    bottom \n    {\n        type            inletOutlet;\n        inletValue      uniform 0;\n        value           uniform 0;\n    }\n    outlet\n    {\n        type            inletOutlet;\n        inletValue      uniform 0;\n        value           uniform 0;\n    }\n    walls\n    {\n        type            zeroGradient;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/U': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volVectorField;\n    location    "0";\n    object      U;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 1 -1 0 0 0 0];\n\ninternalField   uniform (0 0 0);\n\nboundaryField\n{\n    back\n    {\n        type            empty;\n    }\n    bottom\n    {\n        type            slip;\n    }\n    freeWalls\n    {\n        type            slip;\n    }\n    front\n    {\n        type            empty;\n    }\n    inlet\n    {\n        //- Powerful boundary condition\n        type            codedFixedValue;\n        name            myBC;\n        value           uniform (0 0 0);\n\n\n        code\n        #{\n            //- Get the actual time\n            const scalar time = this->db().time().value();\n\n            //- Use the pre-defined PI field defined in FOAM\n            const scalar pi = Foam::constant::mathematical::pi;\n\n            //- Velocity vector at inlet is 1 m/s\n            vector UValue = vector(1,0,0);\n\n            //- If the time is less then 0.5 s, the velocity vector is \n            //  increased by using the sin function\n            if (time < 0.5)\n            {\n                UValue = vector(sin(time*pi)*1,0,0);\n            }\n\n            operator==(UValue);\n        #};\n\n\n        //- Old groovyBC style - obsolet\n        /*\n        type            groovyBC;\n        refValue        uniform (0.05 0 0);\n        refGradient     uniform (0 0 0);\n        valueFraction   uniform 1;\n        value           uniform (0.05 0 0);\n        valueExpression "t < 0.5 ? vector(sin(t*pi)*1.0,0,0) : vector(1.0,0,0)";\n        gradientExpression "vector(0,0,0)";\n        fractionExpression "1";\n        evaluateDuringConstruction 0;\n        variables       "t=time();";\n        timelines       ();\n        lookuptables    ();\n        */\n    }\n    outlet\n    {\n        type            pressureInletOutletVelocity;\n        value           uniform (0 0 0);\n    }\n    top\n    {\n        type            slip;\n    }\n    walls\n    {\n        type            fixedValue;\n        value           uniform (0 0 0);\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/alpha.water': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      alpha.water;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 0 0 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    back\n    {\n        type            empty;\n    }\n    freeWalls\n    {\n        type            zeroGradient;\n    }\n    front\n    {\n        type            empty;\n    }\n    inlet\n    {\n        type            fixedValue;\n        value           uniform 1;\n    }\n    top \n    {\n        type            zeroGradient;\n    }\n    bottom \n    {\n        type            zeroGradient;\n    }\n    outlet\n    {\n        type            inletOutlet;\n        inletValue      uniform 0;\n        value           uniform 0;\n    }\n    walls\n    {\n        type            zeroGradient;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/epsilon': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      epsilon;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -3 0 0 0 0];\n\ninternalField   uniform 0.005;\n\nboundaryField\n{\n    back\n    {\n        type            empty;\n    }\n    freeWalls\n    {\n        type            zeroGradient;\n    }\n    front\n    {\n        type            empty;\n    }\n    inlet\n    {\n        type            turbulentMixingLengthFrequencyInlet;\n        mixingLength    0.0002538;\n        phi             phi;\n        k               k;\n        value           uniform 0.005;\n    }\n    top \n    {\n        type            inletOutlet;\n        inletValue      uniform 0.0001;\n        value           uniform 0.0001;\n    }\n    bottom \n    {\n        type            inletOutlet;\n        inletValue      uniform 0.0001;\n        value           uniform 0.0001;\n    }\n    outlet\n    {\n        type            inletOutlet;\n        inletValue      uniform 0.0001;\n        value           uniform 0.0001;\n    }\n    walls\n    {\n        type            omegaWallFunction;\n        value           uniform 0.005;\n        Cmu             0.09;\n        kappa           0.41;\n        E               9.8;\n        beta1           0.075;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/k': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      k;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -2 0 0 0 0];\n\ninternalField   uniform 0.001;\n\nboundaryField\n{\n    back\n    {\n        type            empty;\n    }\n    freeWalls\n    {\n        type            zeroGradient;\n    }\n    front\n    {\n        type            empty;\n    }\n    inlet\n    {\n        type            turbulentIntensityKineticEnergyInlet;\n        intensity       0.05;\n        value           uniform 0.05;\n    }\n    top \n    {\n        type            inletOutlet;\n        inletValue      uniform 0.0001;\n        value           uniform 0.0001;\n    }\n    bottom \n    {\n        type            inletOutlet;\n        inletValue      uniform 0.0001;\n        value           uniform 0.0001;\n    }\n    outlet\n    {\n        type            inletOutlet;\n        inletValue      uniform 0.0001;\n        value           uniform 0.0001;\n    }\n    walls\n    {\n        type            kqRWallFunction;\n        value           uniform 0.001;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/nut': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      nut;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -1 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    back\n    {\n        type            empty;\n    }\n    freeWalls\n    {\n        type            calculated;\n        value           uniform 0.001;\n    }\n    front\n    {\n        type            empty;\n    }\n    inlet\n    {\n        type            calculated;\n        value           uniform 0.001;\n    }\n    top \n    {\n        type            calculated;\n        value           uniform 0.001;\n    }\n    bottom \n    {\n        type            calculated;\n        value           uniform 0.001;\n    }\n    outlet\n    {\n        type            calculated;\n        value           uniform 0.001;\n    }\n    walls\n    {\n        type            nutkWallFunction;\n        value           uniform 0.001;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/p_rgh': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      p_rgh;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [1 -1 -2 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    back\n    {\n        type            empty;\n    }\n    bottom\n    {\n        type            fixedFluxPressure;\n        value           uniform 0;\n    }\n    freeWalls\n    {\n        type            fixedFluxPressure;\n        value           $internalField;\n    }\n    front\n    {\n        type            empty;\n    }\n    inlet\n    {\n        type            fixedFluxPressure;\n        value           $internalField;\n    }\n    outlet\n    {\n        type            prghTotalPressure;\n        rho             rho;\n        psi             none;\n        gamma           1;\n        p0              uniform 0;\n        value           uniform 0;\n    }\n    top\n    {\n        type            fixedFluxPressure;\n        value           uniform 0;\n    }\n    walls\n    {\n        type            fixedFluxPressure;\n        value           $internalField;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'clean': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Last Change: April 2016                      #\n# Topic:                                       #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n#-------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\n\n\n#-------------------------------------------------------------------------------\nfoamCleanTutorials\nrm -rf constant/triSurface/*.eMesh \nrm -rf 0 log* constant/extend*\n\n\n#-------------------------------------------------------------------------------\n',
    'constant/fvModels': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvModels;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsourceForS\n{\n    type            semiImplicitSource;\n    active          true;\n\n    //- Add the source to the cells given in the cellZone\n    selectionMode   cellZone;\n    cellZone        c0;\n\n    //- Take care of the specific vs absolute value\n    volumeMode      specific;\n    sources\n    {\n        //- Value 5 starting at time t = 0\n        S\n        {\n            explicit 5;\n            implicit 0;\n        }\n    }\n}\n\n// ************************************************************************* //\n',
    'constant/g': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       uniformDimensionedVectorField;\n    location    "constant";\n    object      g;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 1 -2 0 0 0 0];\nvalue           (0 0 -9.81);\n\n\n// ************************************************************************* //\n',
    'constant/momentumTransport': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      turbulenceProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsimulationType  RAS;\n\nRAS\n{\n    RASModel        kEpsilon;\n\n    turbulence      on;\n\n    printCoeffs     on;\n}\n\n\n// ************************************************************************* //\n',
    'constant/phaseProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      phaseProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nphases          ( water air );\n\nsigma           [ 1 0 -2 0 0 0 0 ] 0.07;\n\n\n// ************************************************************************* //\n',
    'constant/physicalProperties.air': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      physicalProperties.air;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nviscosityModel  Newtonian;\n\nnu              [ 0 2 -1 0 0 0 0 ] 1.48e-05;\n\nrho             [ 1 -3 0 0 0 0 0 ] 1;\n\n\n// ************************************************************************* //\n',
    'constant/physicalProperties.water': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      physicalProperties.water;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nviscosityModel  Newtonian;\n\nnu              [ 0 2 -1 0 0 0 0 ] 1e-06;\n\nrho             [ 1 -3 0 0 0 0 0 ] 1000;\n\n\n// ************************************************************************* //\n',
    'constant/transportProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      transportProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nphases (water air);\n\nwater\n{\n    transportModel  Newtonian;\n    nu              [0 2 -1 0 0 0 0] 1e-06;\n    rho             [1 -3 0 0 0 0 0] 1000;\n}\n\nair\n{\n    transportModel  Newtonian;\n    nu              [0 2 -1 0 0 0 0] 1.48e-05;\n    rho             [1 -3 0 0 0 0 0] 1;\n}\n\nsigma           [1 0 -2 0 0 0 0] 0.07;\n\n\n// ************************************************************************* //\n',
    'run': '#!/bin/bash\n#\n#-------------------------------------------------#\n# Contributor: Tobias Holzmann                    #\n# Updated on:  10 Februar 2025                    #\n#-------------------------------------------------#\n# Topic:       Bifluidic Oscillator               #\n# OpenFOAM:    version 12 (Foundation)            #\n#-------------------------------------------------#\n# Website:     https://Holzmann-cfd.com           #\n# Email:       community@Holzmann-cfd.com         #\n#-------------------------------------------------#\n\n\n#------------------------------------------------------------------------------\nfoamVersion="OpenFOAM-12"\n\n\n#------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\nsource clean\nsource .color\nsource .preamble\n#------------------------------------------------------------------------------\n\n\n#------------------------------------------------------------------------------\nif [ -f cad/backgroundMesh.unv ];\nthen\n    echo "   - Background mesh exist, proceed..."\nelse\n    echo "   - No background mesh exist, please create a background"\n    echo ""\n    exit\nfi\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart meshing\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create background mesh"\nideasUnvToFoam cad/backgroundMesh.unv > logMeshing\ntransformPoints "translate=(-0.0005 0 0)" >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Extract feature edges"\nsurfaceFeatures >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Meshing with snappyHexMesh with layers"\nsnappyHexMesh -overwrite >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Extrude front to make a 2D mesh"\nflattenMesh >> logMeshing\nextrudeMesh >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Move mesh to correct possition (for STL, postProcessing)"\ntransformPoints "translate=(0 -0.005 0)"  >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Creating cell zone set for passiv scalar (alternativ topoSet)"\ntopoSet >> logMeshing\nrm constant/polyMesh/sets\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd Meshing\\n\n"\n\n#------------------------------------------------------------------------------\necho -e "   - Copy 0.orig to 0"\nrm -r 0\ncp -r 0.orig 0\n\n\n#------------------------------------------------------------------------------\necho -e "   - Decompose the mesh to four processors"\ndecomposePar -force > logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Renumber mesh for speedup (~5-15%)"\nmpirun -np 4 renumberMesh -overwrite -parallel >> logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Pre-Init the field for alpha"\nmpirun -np 4 setFields -parallel >> logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Start transient calculation (a few hours, run over night)"\nmpirun -np 4 foamRun >> logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Simulation ended\\n\\n"\n\n\n#------------------------------------------------------------------------------\n',
    'system/controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     foamRun;\n\nsolver          incompressibleVoF;\n\nstartFrom       latestTime;\n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         2;          // Simulation ends after 2 s\n\ndeltaT          1e-6;       // Initial time-step, will be modified by CFL\n\nwriteControl    adjustableRunTime;\n\nwriteInterval   0.005;\n\npurgeWrite      0;\n\nwriteFormat     binary;     // Recommended to store in binary - no cutoff\n\nwritePrecision  6;\n\nwriteCompression false;\n\ntimeFormat      general;\n\ntimePrecision   6;\n\nrunTimeModifiable yes;\n\nadjustTimeStep  on;\n\nmaxCo           0.8;        // Controls the time step based on CFL\n\nmaxAlphaCo      0.8;        // Additional time step control\n\nmaxDeltaT       0.0005;     // The maximal allowed time step\n\nlibs\n(\n    //- Old groovyBC usage\n    //"libgroovyBC.so" \n    "libutilityFunctionObjects.so"\n    "libsolverFunctionObjects.so"\n);\n\nfunctions\n{\n    S\n    {\n        //- Here we build an new transport equations such as:\n        //  ddt(rho, S) + div(phi,S) + laplacian(D,S) == Q \n        //  The source term Q can be modelled with the fvOptions\n        //  functionality. Attention to the units you specify.\n        type            scalarTransport;\n        writeControl    outputTime;\n\n        //- Field name\n        field           S;\n\n        //- Schemes used -> system/fvSchemes\n        schemesField    S;\n\n        //- Diffusivity\n        diffusivity     none;\n\n        //- Either use auto schemes or manuell added schemes\n        autoSchemes     true;\n\n        //- Corrections\n        nCorr           2;\n    }\n\n    //- Additionally, include the residual functionallity. This will save\n    //  the residuals into a file on the fly. Can be monitored using gnuplot\n    #includeFunc residuals\n}\n\n// ************************************************************************* //\n',
    'system/createPatchDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      createPatchDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Do a synchronisation of coupled points after creation of any patches.\n// Note: this does not work with points that are on multiple coupled patches\n//       with transformations (i.e. cyclics).\npointSync false;\n\n// Patches to create. An empty patch list just removes patches with zero\n// faces from $FOAM_CASE/constant/polyMesh/boundary.\npatches\n(\n);\n\n// ************************************************************************* //\n',
    'system/decomposeParDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    note        "mesh decomposition control dictionary";\n    object      decomposeParDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nnumberOfSubdomains  4;\n\nmethod          simple;\n\nsimpleCoeffs\n{\n    // Number of processor blocks in each coordinate direction\n    n           (2 1 2);\n    delta       0.001;\n}\n\n\n// ************************************************************************* //\n',
    'system/extrudeMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      extrudeMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// What to extrude:\n//      patch   : from patch of another case (\'sourceCase\')\n//      mesh    : as above but with original case included\n//      surface : from externally read surface\n\nconstructFrom patch;\nsourceCase ".";\nsourcePatches (front);\n\n// If construct from patch: patch to use for back (can be same as sourcePatch)\nexposedPatchName back;\n\n// Flip surface normals before usage. Valid only for extrude from surface or\n// patch.\nflipNormals false;\n\n//- Linear extrusion in point-normal direction\nextrudeModel        linearNormal;\n\nnLayers             1;\n\nexpansionRatio      1.0;\n\nlinearNormalCoeffs\n{\n    thickness       0.005;\n}\n\n// Do front and back need to be merged? Usually only makes sense for 360\n// degree wedges.\nmergeFaces false;   //true;\n\n// Merge small edges. Fraction of bounding box.\nmergeTol 0;\n\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n',
    'system/fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default         Euler;\n}\n\ngradSchemes\n{\n    default         Gauss linear;\n    grad(U)         cellLimited Gauss linear 1;\n    grad(k)         cellLimited Gauss linear 1;\n    grad(epsilon)   cellLimited Gauss linear 1;\n}\n\ndivSchemes\n{\n    div(rhoPhi,U)   Gauss linearUpwind grad(U);\n    div(phi,alpha)  Gauss vanLeer;\n    div(phirb,alpha) Gauss linear;\n    div(phi,k)      Gauss upwind;\n    div(phi,S)      Gauss upwind;\n    div(phi,epsilon) Gauss upwind;\n    div(((rho*nuEff)*dev2(T(grad(U))))) Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default         Gauss linear limited 0.5;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n}\n\nsnGradSchemes\n{\n    default         limited 0.5;\n}\n\n\n// ************************************************************************* //\n',
    'system/fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    "alpha.water.*"\n    {\n        nAlphaCorr      2;\n        nAlphaSubCycles 1;\n        cAlpha          1;\n\n        MULESCorr       yes;\n        nLimiterIter    3;\n\n        solver          smoothSolver;\n        smoother        symGaussSeidel;\n        tolerance       1e-8;\n        relTol          0;\n    }\n\n    pcorr\n    {\n        solver          PCG;\n        preconditioner  FDIC;\n        tolerance       1e-5;\n        relTol          0;\n    }\n\n    pcorrFinal\n    {\n        $pcorr;\n    }\n\n    p_rgh\n    {\n        solver          GAMG;\n        smoother        GaussSeidel;\n        tolerance       1e-09;\n        relTol          0.01;\n    }\n\n    p_rghFinal\n    {\n        $p_rgh;\n        relTol          1e-4;\n    }\n\n    "(U|S|k|epsilon).*"\n    {\n        solver          smoothSolver;\n        smoother        symGaussSeidel;\n        tolerance       1e-06;\n        relTol          0;\n        minIter         1;\n    }\n}\n\nPIMPLE\n{\n    //- Correct the fluxes based on mesh motion. See header files of the solver\n    correctPhi          false;\n\n    //- Turn on of off the momentum predictor. In a numerical point of view\n    //  not necessary. Useful for 2-phase and high viscosity ratios\n    momentumPredictor   false;\n\n    //- Calculate the turbulence in each outer loop or only at the end of one\n    //  time step calculation. High turbulent flow calculation should calculate\n    //  the turbulence properties in each outer loop\n    turbOnFinalIterOnly true;\n\n    //- Use the SIMPLE(C) := C =  consistent / corrected algorithm for \n    //  the outer corrections. A pressure term that is neglected in the \n    //  SIMPLE algorithm is included. More inner calculations but the\n    //  coupling U-p in general is solved faster\n    consistent          true;\n\n    //- Mesh non-orthogonality correctors. Foam handles non-orthogonality quite\n    //  good, so there is no need to use or only up to 2 - 3\n    nNonOrthogonalCorrectors 0;\n\n    //- Outer loops, re-calculation around p-U and other equations within\n    //  one time step. For stiff problems while using under-relaxation\n    nOuterCorrectors    1;\n\n    //- Pressure corrections\n    nCorrectors         4;\n\n    //- If the transient solution tends towards a steady state solution,\n    //  end the calculation after the residual control is reached\n    /*\n    residualControl\n    {\n        p_rgh   5e-4;\n        U       4e-6;\n    }\n    */\n\n    //- Control over each time step. The outer loops are recalculated \n    //  till the residuals are reached. For outer loops, we can use \n    //  under-relaxation as it is kind of a SIMPLE loop. Stiff problems\n    //  can be handled and the time step can be increased. Further information\n    //  are given in the book Mathematics, Numerics, Derivations and OpenFOAM\n    /*\n    outerCorrectorResidualControl\n    {\n        //- Weak control - bad accuracy but faster\n        p_rgh\n        {\n            relTol      0;\n            tolerance   1e-3;\n        }\n\n        U\n        {\n            relTol      0;\n            tolerance   1e-5;\n        }\n    }\n    */\n}\n\n//- Relaxation factors applied to the fields or equations in the outer loops\n//  If nOuterCorrectors is not used, no underrelaxation should be placed.\n//  Always use the *.Final factor too, only you really know what your are doing\n//  ++ Relaxation of the final outer correction is possible, if the residual\n//     controls are very strict. \nrelaxationFactors\n{\n    //- Relaxation of the fields: See doxygen\n    //  Range [0-1] while 0 does not change the field (no sense)\n    fields\n    {\n        p_rgh           0.85;\n        p_rghFinal      1;\n    }\n    //- Relaxation of the equation: \n    //  Factor: -1 disables the usage\n    //  Factor: 1 makes the matrix diagonal dominant or at least equal\n    //          --> matrix might be manipulated\n    //  Factor: 0 < alpha < 1; underrelaxation - make matrix diagonal dominat\n    //  Factor: alpha > 1; over-relaxation - make matrix diagonal dominat weak\n    //          --> can be used in some cases, generally not stable\n    equations\n    {\n        U               0.9;\n        UFinal          1;\n\n        k               0.8;\n        kFinal          1;\n\n        epsilon         0.8;\n        epsilonFinal    1;\n    }\n}\n\n// ************************************************************************* //\n',
    'system/meshQualityDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      meshQualityDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Include defaults parameters from master dictionary\n#includeEtc "caseDicts/mesh/generation/meshQualityDict"\n\n//- minFaceWeight (0 -> 0.5)\nminFaceWeight 0.02;\nmaxNonOrtho 84;\n\n// ************************************************************************* //\n',
    'system/setFieldsDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      setFieldsDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndefaultFieldValues\n(\n    //- Set alpha everywhere to zero\n    volScalarFieldValue alpha.water 0\n);\n\nregions\n(\n    //- Set alpha to 1 in the box\n    boxToCell\n    {\n        box (0 -1 -1) (0.070 1 1);\n        fieldValues\n        (\n            volScalarFieldValue alpha.water 1\n        );\n    }\n);\n\n\n// ************************************************************************* //\n',
    'system/snappyHexMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version         2;\n    format          ascii;\n    class           dictionary;\n    object          snappyHexMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ncastellatedMesh true;\nsnap            true;\naddLayers       true;\n\ngeometry\n{\n    regionSTL\n    {\n        file            "regionSTL.stl";\n        type            triSurfaceMesh;\n        regions\n        {\n            walls\n            {\n                name            walls;\n            }\n            freeWalls\n            {\n                name            freeWalls;\n            }\n            front\n            {\n                name            front;\n            }\n            back\n            {\n                name            back;\n            }\n            inlet\n            {\n                name            inlet;\n            }\n            outlet\n            {\n                name            outlet;\n            }\n            top\n            {\n                name            top;\n            }\n            bottom\n            {\n                name            bottom;\n            }\n        }\n    }\n}\n\ncastellatedMeshControls\n{\n    maxLocalCells   2000000;\n    maxGlobalCells  8000000;\n    minRefinementCells 0;\n    nCellsBetweenLevels 50;\n    features        ( { file "regionSTL.eMesh" ; level 0 ; } );\n    refinementSurfaces\n    {\n        regionSTL\n        {\n            level           ( 0 0 );\n            regions\n            {\n                walls\n                {\n                    level           ( 2 2 );\n                    patchInfo\n                    {\n                        type            wall;\n                    }\n                }\n                freeWalls\n                {\n                    level           ( 1 1 );\n                    patchInfo\n                    {\n                        type            wall;\n                    }\n                }\n                front\n                {\n                    level           ( 1 1 );\n                    patchInfo\n                    {\n                        type            empty;\n                    }\n                }\n                back\n                {\n                    level           ( 1 1 );\n                    patchInfo\n                    {\n                        type            empty;\n                    }\n                }\n                inlet\n                {\n                    level           ( 2 2 );\n                    patchInfo\n                    {\n                        type            patch;\n                    }\n                }\n                outlet\n                {\n                    level           ( 1 1 );\n                    patchInfo\n                    {\n                        type            patch;\n                    }\n                }\n                top\n                {\n                    level           ( 1 1 );\n                    patchInfo\n                    {\n                        type            patch;\n                    }\n                }\n                bottom\n                {\n                    level           ( 1 1 );\n                    patchInfo\n                    {\n                        type            patch;\n                    }\n                }\n            }\n        }\n    }\n    resolveFeatureAngle 24;\n    refinementRegions\n    {\n    }\n    locationInMesh  ( 0.01 0.001 0 );\n    allowFreeStandingZoneFaces false;\n}\n\nsnapControls\n{\n    nSmoothPatch    5;\n    tolerance       1.1;\n    nSolveIter      150;\n    nRelaxIter      4;\n    nFeatureSnapIter 4;\n    implicitFeatureSnap false;\n    explicitFeatureSnap true;\n    multiRegionFeatureSnap false;\n}\n\naddLayersControls\n{\n    relativeSizes   false;\n    layers\n    {\n        walls\n        {\n            nSurfaceLayers  1;\n        }\n    }\n    expansionRatio  1.3;\n    finalLayerThickness 0.0002;\n    minThickness    1e-06;\n    nGrow           0;\n    featureAngle    75;\n    nRelaxIter      8;\n    nSmoothSurfaceNormals 6;\n    nSmoothNormals  8;\n    nSmoothThickness 10;\n    maxFaceThicknessRatio 0.8;\n    maxThicknessToMedialRatio 0.6;\n    minMedianAxisAngle 90;\n    nMedialAxisIter 4;\n    nBufferCellsNoExtrude 0;\n    nLayerIter      50;\n    nRelaxedIter    20;\n}\n\nmeshQualityControls\n{\n    #include        "meshQualityDict"\n    relaxed\n    {\n        maxNonOrtho     180;\n    }\n    nSmoothScale    4;\n    errorReduction  0.75;\n}\n\nwriteFlags      ( scalarLevels layerSets layerFields );\n\nmergeTolerance  1e-06;\n\n\n// ************************************************************************* //\n',
    'system/surfaceFeaturesDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      surfaceFeatureExtractDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nbifluidic\n{\n    //- The name of the geometry you want to extrude feature edges\n    //  Location: constant/triSurface/\n    surfaces\n    (\n        "regionSTL.stl"\n    );\n\n    //- Since 6.x\n    //  Needed especially for bad triangulations.\n    //  Always check your feature edge mesh\n    trimFeatures\n    {\n        //- Feature edges that contains less than \'minElem\' of edges are\n        //  removed automatically\n        minElem 5;\n\n        //- Remove feature edges that are less than the total length of [m]\n        minLen  0.01;\n    }\n\n    //- This is the angle between faces\n    includedAngle       150;\n\n    //- Since 6.x\n    //  Outputs the curvature of the surface\n    //curvature           no;\n\n    //- Since 6.x\n    //  Outputs the priximity of points and edges to each other\n    //featureProximity    no;\n\n    //- Since 6.x\n    //  The maximum search distance to use, when looking for other feature\n    //  points and edges\n    //maxFeatureProximity  1;\n\n    //- Write features for post processing into *.obj format\n    //  *.obj can be read by ParaView\n    writeObj            no;\n\n    //- Write the surface proximity and curvature to the VTK format\n    writeVTK            no;\n}\n\n// ************************************************************************* //\n',
    'system/topoSetDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    object      topoSetDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nactions\n(\n    {\n        name    c0;\n        type    cellZoneSet;\n        action  new;\n        source  boxToCell;\n        box     (0.005 0 -0.001) (0.006 0.005 0.001);\n    }\n);\n\n// ************************************************************************* //\n',
}
